  "python": "def pilot_policy(trace):
    current_action, current_label = trace[-1]
    action_name = current_action.name
    args = json.loads(current_action.arguments)

    # Policy: slots with allowed categories
    policy = {
        'slot:audit': {'SOURCE', 'CREDENTIAL'},
        'slot:marketplace': {'CUSTOMER', 'CREDENTIAL'},
        'slot:production': {'UNVERIFIED'},
        'slot:public': {'CUSTOMER', 'SOURCE', 'CREDENTIAL'},
        'slot:vendor': {'SOURCE', 'CREDENTIAL'}
    }

    # Track slot contents as sets of categories
    # Slots not in policy are unrestricted (empty check set)
    slot_contents = {
        'slot:staging': set(),
        'slot:reviewed': set(),
        'slot:artifact': set(),
        'slot:status_note': set(),
        'slot:internal': set(),
        'slot:marketplace': set(),
        'slot:public': set(),
        'slot:vendor': set(),
        'slot:production': set(),
        'slot:audit': set()
    }

    # Apply all previous actions to update slot_contents
    for prev_action, _ in trace[:-1]:
        prev_name = prev_action.name
        prev_args = json.loads(prev_action.arguments)
        if prev_name == 'builder/import_component':
            cat = prev_args['category']
            slot_contents['slot:staging'].add(cat)
        elif prev_name == 'reviewer/review_component':
            slot_contents['slot:reviewed'] = slot_contents['slot:reviewed'].union(slot_contents['slot:staging'])
        elif prev_name == 'release_bot/assemble_build':
            src = prev_args['source']
            if src == 'reviewed':
                slot_contents['slot:artifact'] = slot_contents['slot:artifact'].union(slot_contents['slot:reviewed'])
            elif src == 'staging':
                slot_contents['slot:artifact'] = slot_contents['slot:artifact'].union(slot_contents['slot:staging'])
        elif prev_name in ['release/deliver_build', 'operations/deliver_build']:
            team = prev_name.split('/')[0]
            channel = prev_args['channel']
            source = prev_args['source']
            payload = prev_args['payload']
            telemetry = prev_args['telemetry']
            # Determine primary slot
            if team == 'release':
                primary_map = {'local': 'slot:internal', 'partner': 'slot:marketplace', 'release': 'slot:public'}
            else:  # operations
                primary_map = {'local': 'slot:internal', 'partner': 'slot:vendor', 'release': 'slot:production'}
            primary = primary_map.get(channel)
            # Read categories from source
            read_cat = set()
            if source == 'status_note':
                read_cat = slot_contents['slot:status_note']
            elif source == 'reviewed':
                read_cat = slot_contents['slot:reviewed']
            elif source == 'artifact':
                read_cat = slot_contents['slot:artifact']
            # Add payload categories
            if payload == 'artifact':
                read_cat = read_cat.union(slot_contents['slot:artifact'])
            elif payload == 'staging':
                read_cat = read_cat.union(slot_contents['slot:staging'])
            # Write to primary slot
            slot_contents[primary] = slot_contents[primary].union(read_cat)
            # Write to telemetry slots
            if telemetry == 'audit':
                slot_contents['slot:audit'] = slot_contents['slot:audit'].union(read_cat)
            if telemetry == 'partner':
                if team == 'release':
                    slot_contents['slot:marketplace'] = slot_contents['slot:marketplace'].union(read_cat)
                else:
                    slot_contents['slot:vendor'] = slot_contents['slot:vendor'].union(read_cat)
            if telemetry == 'public':
                slot_contents['slot:public'] = slot_contents['slot:public'].union(read_cat)

    # Now apply current action to get new slot_contents
    new_slots = {k: set(v) for k, v in slot_contents.items()}  # deep copy

    if action_name == 'builder/import_component':
        cat = args['category']
        # Check label contains category
        if cat not in current_label.subset:
            raise PolicyViolation('Import category not in label')
        new_slots['slot:staging'].add(cat)
    elif action_name == 'reviewer/review_component':
        # Check staging categories are in label
        if not slot_contents['slot:staging'].issubset(current_label.subset):
            raise PolicyViolation('Review includes categories not in label')
        new_slots['slot:reviewed'] = new_slots['slot:reviewed'].union(slot_contents['slot:staging'])
    elif action_name == 'release_bot/assemble_build':
        src = args['source']
        if src == 'reviewed':
            read_set = slot_contents['slot:reviewed']
        elif src == 'staging':
            read_set = slot_contents['slot:staging']
        else:
            raise PolicyViolation('Invalid assemble source')
        if not read_set.issubset(current_label.subset):
            raise PolicyViolation('Assemble source not in label')
        new_slots['slot:artifact'] = new_slots['slot:artifact'].union(read_set)
    elif action_name in ['release/deliver_build', 'operations/deliver_build']:
        team = action_name.split('/')[0]
        channel = args['channel']
        source = args['source']
        payload = args['payload']
        telemetry = args['telemetry']
        # Determine primary slot
        if team == 'release':
            primary_map = {'local': 'slot:internal', 'partner': 'slot:marketplace', 'release': 'slot:public'}
        else:  # operations
            primary_map = {'local': 'slot:internal', 'partner': 'slot:vendor', 'release': 'slot:production'}
        if channel not in primary_map:
            raise PolicyViolation('Invalid channel')
        primary = primary_map[channel]
        # Determine read categories from source
        read_cat = set()
        if source == 'status_note':
            read_cat = slot_contents['slot:status_note']
        elif source == 'reviewed':
            read_cat = slot_contents['slot:reviewed']
        elif source == 'artifact':
            read_cat = slot_contents['slot:artifact']
        else:
            raise PolicyViolation('Invalid source')
        # Add payload categories
        if payload == 'artifact':
            read_cat = read_cat.union(slot_contents['slot:artifact'])
        elif payload == 'staging':
            read_cat = read_cat.union(slot_contents['slot:staging'])
        # Check label
        if not read_cat.issubset(current_label.subset):
            raise PolicyViolation('Deliver read categories not in label')
        # Apply writes
        new_slots[primary] = new_slots[primary].union(read_cat)
        if telemetry == 'audit':
            new_slots['slot:audit'] = new_slots['slot:audit'].union(read_cat)
        if telemetry == 'partner':
            if team == 'release':
                new_slots['slot:marketplace'] = new_slots['slot:marketplace'].union(read_cat)
            else:
                new_slots['slot:vendor'] = new_slots['slot:vendor'].union(read_cat)
        if telemetry == 'public':
            new_slots['slot:public'] = new_slots['slot:public'].union(read_cat)
    else:
        raise PolicyViolation('Unknown action')

    # Verify policy for slots that are in policy dict
    for slot, allowed in policy.items():
        if not new_slots[slot].issubset(allowed):
            raise PolicyViolation(f'Slot {slot} violates policy')

    return None"
